// Jonas -- Anruf-Erkennung, Node 1: Payload von Tasker normalisieren.
// Erwartetes Tasker-Payload (JSON-Body im HTTP-Request-Task):
//   { "number": "%CNUM", "contactName": "%CNAME", "callType": "missed|answered", "timestamp": "%TIME" }
// contactName ist leer/fehlt, wenn Android die Nummer keinem lokalen Kontakt zuordnen konnte --
// das ist bereits die erste, kostenlose Abgleich-Stufe (laeuft lokal auf dem Handy, kein Server noetig).
//
// WICHTIG: tenant_id ist hier ein Platzhalter -- vor dem Import mit der echten tenant_id
// aus der tenants-Tabelle ersetzen (SELECT tenant_id FROM tenants WHERE telegram_chat_id = ...).
const TENANT_ID = 'TENANT_ID_HIER_EINTRAGEN';

const body = $input.first().json.body || $input.first().json;
const number = String(body.number || '').trim();
const contactName = String(body.contactName || '').trim();
const callType = (body.callType === 'missed') ? 'missed' : 'answered';

return [{
  json: {
    tenant_id: TENANT_ID,
    number,
    contactName,
    hasContact: contactName.length > 0,
    callType
  }
}];

// Prueft ob Tellows einen brauchbaren Treffer geliefert hat (Name oder genug Meldungen).
// Feldnamen (tellows.score/comments/name) gemaess oeffentlich bekanntem Basic-API-Format --
// bei Bedarf an die tatsaechliche Antwortstruktur anpassen, sobald ein echter Test lief.
const t = ($json.tellows) || $json;
const score = t.score != null ? Number(t.score) : null;
const comments = t.comments != null ? Number(t.comments) : 0;
const name = (t.name || '').trim();
const hasHit = comments > 0 || !!name;
return [{ json: { tellowsHit: hasHit, tellowsName: name, tellowsScore: score } }];

// Nimmt den Titel/Snippet des ersten Suchtreffers als grobe Identifikation --
// bewusst simpel gehalten (kein LLM-Call noetig fuer v1), liefert oft schon einen
// Firmennamen oder Hinweis ('Spam gemeldet auf...') aus dem Snippet.
const results = ($json.web && $json.web.results) || [];
const first = results[0];
const guess = first ? `${first.title || ''} -- ${first.description || ''}`.trim() : '';
return [{ json: { braveGuess: guess } }];

// Jonas -- Anruf-Erkennung: fasst alle drei Abgleich-Stufen zu EINER Identifikation zusammen.
// Reihenfolge/Prioritaet: Android-Kontakt > Tellows-Treffer > Brave-Search-Vermutung > unbekannt.
const base = $('Anruf normalisieren').item.json;
let identifiedAs = null;
let source = 'unbekannt';
let spamScore = null;

if (base.hasContact) {
  identifiedAs = base.contactName;
  source = 'kontakt';
} else {
  const tellows = $('Tellows Ergebnis pruefen').first();
  if (tellows && tellows.json.tellowsHit) {
    identifiedAs = tellows.json.tellowsName || `Score ${tellows.json.tellowsScore} (Tellows, kein Name)`;
    source = 'tellows';
    spamScore = tellows.json.tellowsScore;
  } else {
    const brave = $('Brave Ergebnis zusammenfassen').first();
    if (brave && brave.json.braveGuess) {
      identifiedAs = brave.json.braveGuess;
      source = 'brave_search';
    }
  }
}

return [{
  json: {
    tenant_id: base.tenant_id,
    number: base.number,
    callType: base.callType,
    identifiedAs,
    source,
    spamScore
  }
}];

